/**
 * Hand-off bench state: a ticket the desk issues with app-generated values
 * (code, colour, desk number) that appear on screen once and nowhere else.
 * A later step at the gate must reproduce them, so the only path is the
 * step ledger. Regenerated by `POST /api/reset`, readable for assertions.
 */

export interface Ticket {
  code: string;
  colour: string;
  desk: number;
  issued: boolean;
}

interface HandoffStore {
  ticket: Ticket;
  granted: string | null;
}

const COLOURS = ['Amber', 'Teal', 'Violet', 'Crimson', 'Olive'];

function seeded(): HandoffStore {
  const digits = String(1000 + Math.floor(Math.random() * 9000));
  return {
    ticket: {
      code: `TK-${digits}`,
      colour: COLOURS[Math.floor(Math.random() * COLOURS.length)]!,
      desk: 1 + Math.floor(Math.random() * 9),
      issued: false,
    },
    granted: null,
  };
}

const holder = globalThis as typeof globalThis & { e2eHandoffStore?: HandoffStore };

function store(): HandoffStore {
  holder.e2eHandoffStore ??= seeded();
  return holder.e2eHandoffStore;
}

export function resetHandoff(): void {
  holder.e2eHandoffStore = seeded();
}

export function readHandoff(): HandoffStore {
  return JSON.parse(JSON.stringify(store())) as HandoffStore;
}

/**
 * Issues the ticket. A second issue hands out a NEW code: a step that goes
 * back to the desk to look the ticket up again gets a different ticket, so
 * only what an earlier step handed over opens the gate for the original one.
 */
export function issueTicket(): Ticket {
  const state = store();
  if (state.ticket.issued) {
    state.ticket = { ...state.ticket, code: `TK-${String(1000 + Math.floor(Math.random() * 9000))}` };
  }
  state.ticket.issued = true;
  return { ...state.ticket };
}

/** Checks the gate entry; the colour is compared case-insensitively. */
export function enterGate(
  code: string,
  colour: string,
  desk: string,
): { granted: boolean; message: string } {
  const { ticket } = store();
  const ok =
    ticket.issued &&
    code.trim().toUpperCase() === ticket.code &&
    colour.trim().toLowerCase() === ticket.colour.toLowerCase() &&
    Number(desk) === ticket.desk;
  store().granted = ok ? ticket.code : null;
  return ok
    ? { granted: true, message: `Access granted for ${ticket.code} (${ticket.colour}, desk ${String(ticket.desk)})` }
    : { granted: false, message: 'Access denied: the code, colour or desk does not match the issued ticket' };
}
